//! `Decoder::output_params` / `output_params_generation` (oxideav-core
//! 0.1.42): the decoder states the shape of the frames it emits once,
//! at the stream level, instead of in every frame.
//!
//! Gates, on black-box libx264 fixtures (`tests/fixtures/output_params/`,
//! regenerated by `gen.sh` there, which also records what `ffprobe`
//! reports in `expected.txt`) plus the crate's own encoder for the
//! layouts libx264 cannot produce (4:0:0, separate colour planes):
//!
//! * the answer is available from the `avcC` record right after
//!   construction, before any packet, and equals the answer after the
//!   first frame;
//! * every emitted frame's planes have exactly the geometry the answer
//!   states (§7.4.2.1.1 cropped size, Table 6-1 chroma subsampling,
//!   bytes per sample of the bit depth), and the answer matches
//!   `ffprobe` (width, height, pix_fmt, colour range / primaries /
//!   transfer / matrix; frame rate = half ffprobe's raw-ES tick rate);
//! * a stream whose second coded video sequence changes size and bit
//!   depth bumps the generation exactly once, at the first frame of the
//!   new shape;
//! * the answers and generations after every frame are identical with
//!   1 and 8 worker threads.

use oxideav_core::{
    CodecId, CodecParameters, ColorRange, ColorSignal, Decoder, ExecutionContext, Frame,
    OutputParamsWatch, Packet, PixelFormat, Rational, TimeBase, VideoFrame,
};
use oxideav_h264::h264_decoder::{H264CodecDecoder, make_decoder};

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/output_params");

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("{DIR}/{name}")).expect("fixture")
}

/// Split an Annex B byte stream into NAL unit payloads (no start code).
fn nal_payloads(data: &[u8]) -> Vec<&[u8]> {
    let mut starts = Vec::new();
    let mut i = 0usize;
    while i + 3 <= data.len() {
        if data[i] == 0 && data[i + 1] == 0 && data[i + 2] == 1 {
            starts.push(i + 3);
            i += 3;
        } else {
            i += 1;
        }
    }
    (0..starts.len())
        .map(|k| {
            let mut end = starts.get(k + 1).map(|&s| s - 3).unwrap_or(data.len());
            while end > starts[k] && data[end - 1] == 0 {
                end -= 1;
            }
            &data[starts[k]..end]
        })
        .collect()
}

/// One expected.txt row: what ffprobe reported.
struct Probe {
    width: u32,
    height: u32,
    pix_fmt: String,
    range: String,
    space: String,
    transfer: String,
    primaries: String,
    r_frame_rate: (i64, i64),
    frames: usize,
}

fn probe(name: &str) -> Probe {
    let text = std::fs::read_to_string(format!("{DIR}/expected.txt")).expect("expected.txt");
    let line = text
        .lines()
        .find(|l| l.split_whitespace().next() == Some(name))
        .unwrap_or_else(|| panic!("{name} not in expected.txt"));
    let get = |k: &str| {
        line.split_whitespace()
            .find_map(|kv| kv.strip_prefix(&format!("{k}=")).map(str::to_owned))
            .unwrap_or_else(|| panic!("{name}: no {k}"))
    };
    let rate = get("r_frame_rate");
    let (n, d) = rate.split_once('/').expect("rate");
    Probe {
        width: get("width").parse().unwrap(),
        height: get("height").parse().unwrap(),
        pix_fmt: get("pix_fmt"),
        range: get("color_range"),
        space: get("color_space"),
        transfer: get("color_transfer"),
        primaries: get("color_primaries"),
        r_frame_rate: (n.parse().unwrap(), d.parse().unwrap()),
        frames: get("nb_read_frames").parse().unwrap(),
    }
}

/// ffprobe pix_fmt → (layout, implied full range). The `yuvj*` names
/// are ffprobe's spelling of a full-range stream.
fn ffprobe_pix_fmt(s: &str) -> (PixelFormat, bool) {
    match s {
        "yuv420p" => (PixelFormat::Yuv420P, false),
        "yuvj420p" => (PixelFormat::Yuv420P, true),
        "yuv422p" => (PixelFormat::Yuv422P, false),
        "yuvj422p" => (PixelFormat::Yuv422P, true),
        "yuv444p" => (PixelFormat::Yuv444P, false),
        "yuvj444p" => (PixelFormat::Yuv444P, true),
        "yuv420p10le" => (PixelFormat::Yuv420P10Le, false),
        "yuv422p10le" => (PixelFormat::Yuv422P10Le, false),
        "yuv444p10le" => (PixelFormat::Yuv444P10Le, false),
        "gray" => (PixelFormat::Gray8, false),
        other => panic!("unmapped ffprobe pix_fmt {other}"),
    }
}

/// ffprobe colour names → H.273 code points (2 = unspecified).
fn h273(s: &str) -> u8 {
    match s {
        "unknown" => 2,
        "bt709" => 1,
        "bt470bg" => 5,
        "smpte170m" => 6,
        "bt2020" | "bt2020nc" => 9,
        "smpte2084" => 16,
        other => panic!("unmapped ffprobe colour name {other}"),
    }
}

fn reduce(n: i64, d: i64) -> Rational {
    let (mut a, mut b) = (n, d);
    while b != 0 {
        (a, b) = (b, a % b);
    }
    Rational::new(n / a, d / a)
}

/// Assert `p` is what ffprobe reported for the fixture.
fn assert_matches_probe(p: &CodecParameters, pr: &Probe, tag: &str) {
    assert_eq!(p.width, Some(pr.width), "{tag}: width");
    assert_eq!(p.height, Some(pr.height), "{tag}: height");
    let (pf, j_full) = ffprobe_pix_fmt(&pr.pix_fmt);
    assert_eq!(p.pixel_format, Some(pf), "{tag}: pixel format");
    let range = match pr.range.as_str() {
        "tv" => ColorRange::Limited,
        "pc" => ColorRange::Full,
        _ => ColorRange::Unspecified,
    };
    if j_full {
        assert_eq!(range, ColorRange::Full, "{tag}: yuvj implies pc");
    }
    let mut want = ColorSignal::from_code_points(
        h273(&pr.primaries),
        h273(&pr.transfer),
        h273(&pr.space),
        range == ColorRange::Full,
    );
    want.range = range;
    assert_eq!(p.color_signal, want, "{tag}: colour signal");
    // Raw-ES ffprobe reports the tick rate, twice the frame rate.
    let (n, d) = pr.r_frame_rate;
    assert_eq!(p.frame_rate, Some(reduce(n, 2 * d)), "{tag}: frame rate");
}

/// Bytes per sample row / rows of each plane `pf` stores at `w` x `h`.
fn plane_geometry(pf: PixelFormat, w: usize, h: usize) -> Vec<(usize, usize)> {
    use PixelFormat::*;
    let (bps, sub, planes) = match pf {
        Gray8 => (1, (1, 1), 1),
        Gray10Le | Gray12Le => (2, (1, 1), 1),
        Yuv420P => (1, (2, 2), 3),
        Yuv422P => (1, (2, 1), 3),
        Yuv444P => (1, (1, 1), 3),
        Yuv420P10Le | Yuv420P12Le => (2, (2, 2), 3),
        Yuv422P10Le | Yuv422P12Le => (2, (2, 1), 3),
        Yuv444P10Le | Yuv444P12Le => (2, (1, 1), 3),
        other => panic!("unexpected layout {other:?}"),
    };
    let mut g = vec![(w * bps, h)];
    for _ in 1..planes {
        g.push((w.div_ceil(sub.0) * bps, h.div_ceil(sub.1)));
    }
    g
}

/// Assert the frame's planes are exactly what `p` describes.
fn assert_frame_matches(vf: &VideoFrame, p: &CodecParameters, tag: &str) {
    let geom = plane_geometry(
        p.pixel_format.expect("pixel format"),
        p.width.unwrap() as usize,
        p.height.unwrap() as usize,
    );
    let got: Vec<(usize, usize)> = vf
        .planes
        .iter()
        .map(|pl| (pl.stride, pl.data.len() / pl.stride.max(1)))
        .collect();
    assert_eq!(got, geom, "{tag}: plane geometry vs output_params");
    for pl in &vf.planes {
        assert_eq!(pl.data.len() % pl.stride, 0, "{tag}: whole rows");
    }
}

/// The decoder-owned fields of an `output_params` answer.
#[derive(Clone, Debug, PartialEq)]
struct Desc {
    width: Option<u32>,
    height: Option<u32>,
    pixel_format: Option<PixelFormat>,
    frame_rate: Option<Rational>,
    color_signal: ColorSignal,
}

impl Desc {
    fn of(p: &CodecParameters) -> Self {
        Self {
            width: p.width,
            height: p.height,
            pixel_format: p.pixel_format,
            frame_rate: p.frame_rate,
            color_signal: p.color_signal,
        }
    }
}

/// `(output_params, generation)` after each frame, the frames' plane
/// geometry checked against the answer.
type Trace = Vec<(CodecParameters, u64)>;

fn descs(t: &Trace) -> Vec<(Desc, u64)> {
    t.iter().map(|(p, g)| (Desc::of(p), *g)).collect()
}

fn drain(dec: &mut dyn Decoder, trace: &mut Trace, tag: &str) {
    while let Ok(f) = dec.receive_frame() {
        let Frame::Video(vf) = f else {
            panic!("{tag}: non-video frame")
        };
        let p = dec.output_params().expect("answer after a frame");
        assert_frame_matches(&vf, &p, tag);
        assert_eq!(
            dec.output_pixel_format(),
            p.pixel_format,
            "{tag}: forwarded"
        );
        trace.push((p, dec.output_params_generation()));
    }
}

/// Decode an Annex B stream one NAL per packet, draining after each.
fn decode_streamed(bytes: &[u8], threads: usize, tag: &str) -> Trace {
    let mut dec = H264CodecDecoder::new(CodecId::new("h264"));
    dec.set_execution_context(&ExecutionContext::with_threads(threads));
    let mut trace = Vec::new();
    for (i, nal) in nal_payloads(bytes).into_iter().enumerate() {
        let mut d = vec![0, 0, 0, 1];
        d.extend_from_slice(nal);
        let pkt = Packet::new(0, TimeBase::new(1, 25), d).with_pts(i as i64);
        let _ = dec.send_packet(&pkt);
        drain(&mut dec, &mut trace, tag);
    }
    dec.flush().expect("flush");
    drain(&mut dec, &mut trace, tag);
    trace
}

/// `avcC` from the stream's first SPS / PPS (the §5.2.4.1.1 trailer is
/// optional for the decoder) and the remaining NAL units as 4-byte
/// length-prefixed packets, one per NAL.
fn to_avcc(bytes: &[u8]) -> (Vec<u8>, Vec<Vec<u8>>) {
    let nals = nal_payloads(bytes);
    let sps = nals.iter().find(|n| n[0] & 0x1f == 7).expect("sps");
    let pps = nals.iter().find(|n| n[0] & 0x1f == 8).expect("pps");
    let mut rec = vec![1, sps[1], sps[2], sps[3], 0xff, 0xe1];
    rec.extend_from_slice(&(sps.len() as u16).to_be_bytes());
    rec.extend_from_slice(sps);
    rec.push(1);
    rec.extend_from_slice(&(pps.len() as u16).to_be_bytes());
    rec.extend_from_slice(pps);
    let packets = nals
        .iter()
        .filter(|n| !matches!(n[0] & 0x1f, 7 | 8))
        .map(|n| {
            let mut p = (n.len() as u32).to_be_bytes().to_vec();
            p.extend_from_slice(n);
            p
        })
        .collect();
    (rec, packets)
}

const LAYOUT_FIXTURES: &[&str] = &[
    "yuv420p_70x46_25.h264",
    "yuv422p_64x48_30.h264",
    "yuv444p_48x32_24.h264",
    "yuv420p10_64x48_50.h264",
    "yuv422p10_48x32_25.h264",
    "yuv444p10_32x32_25.h264",
];

#[test]
fn answer_from_avcc_before_the_first_frame_matches_ffprobe_and_frames() {
    for &name in LAYOUT_FIXTURES {
        let pr = probe(name);
        let (avcc, packets) = to_avcc(&fixture(name));
        let mut params = CodecParameters::video(CodecId::new("h264"));
        params.extradata = avcc;
        let mut dec = make_decoder(&params).expect("make_decoder");
        let before = dec.output_params().expect("answer from avcC");
        assert_matches_probe(&before, &pr, &format!("{name} (avcC)"));
        assert_eq!(dec.output_params_generation(), 0);

        // The consumer helper folds it into the stream up front.
        let mut stream = params.clone();
        let watch = OutputParamsWatch::new();
        assert!(watch.prime(&*dec, &mut stream), "{name}: prime fills");
        assert_eq!(stream.width, Some(pr.width));
        assert_eq!(stream.extradata, params.extradata, "container field kept");

        let mut trace = Vec::new();
        for (i, p) in packets.into_iter().enumerate() {
            let pkt = Packet::new(0, TimeBase::new(1, 25), p).with_pts(i as i64);
            dec.send_packet(&pkt).expect("send");
            drain(&mut *dec, &mut trace, name);
        }
        dec.flush().expect("flush");
        drain(&mut *dec, &mut trace, name);
        assert_eq!(trace.len(), pr.frames, "{name}: frame count vs ffprobe");
        for (p, generation) in &trace {
            assert_eq!(Desc::of(p), Desc::of(&before), "{name}: stable answer");
            assert_eq!(*generation, 0, "{name}: no change, no bump");
        }
    }
}

#[test]
fn annex_b_answers_match_ffprobe_at_1_and_8_threads() {
    for &name in LAYOUT_FIXTURES {
        let pr = probe(name);
        let bytes = fixture(name);
        let t1 = decode_streamed(&bytes, 1, name);
        let t8 = decode_streamed(&bytes, 8, name);
        assert_eq!(t1.len(), pr.frames, "{name}: frame count");
        for (p, generation) in &t1 {
            assert_matches_probe(p, &pr, name);
            assert_eq!(*generation, 0);
        }
        assert_eq!(descs(&t1), descs(&t8), "{name}: 1 vs 8 threads");
    }
}

#[test]
fn generation_bumps_exactly_at_the_first_frame_of_the_new_shape() {
    let bytes = fixture("change_64x48_8bit_then_48x32_10bit.h264");
    for threads in [1, 8] {
        let trace = decode_streamed(&bytes, threads, "change");
        let shapes: Vec<(u32, u32, PixelFormat, u64)> = trace
            .iter()
            .map(|(p, g)| {
                (
                    p.width.unwrap(),
                    p.height.unwrap(),
                    p.pixel_format.unwrap(),
                    *g,
                )
            })
            .collect();
        let mut want = vec![(64, 48, PixelFormat::Yuv420P, 0); 5];
        want.extend(vec![(48, 32, PixelFormat::Yuv420P10Le, 1); 5]);
        assert_eq!(shapes, want, "{threads} thread(s)");
    }
    assert_eq!(
        descs(&decode_streamed(&bytes, 1, "change")),
        descs(&decode_streamed(&bytes, 8, "change"))
    );

    // Whole stream queued before the first receive: the new SPS has been
    // parsed long before the old-shape frames come out, and the answer
    // still follows the frames.
    let mut dec = H264CodecDecoder::new(CodecId::new("h264"));
    dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), bytes.clone()).with_pts(0))
        .expect("send");
    dec.flush().expect("flush");
    let mut stream = CodecParameters::video(CodecId::new("h264"));
    let mut watch = OutputParamsWatch::new();
    watch.prime(&dec, &mut stream);
    assert_eq!((stream.width, stream.height), (Some(64), Some(48)));
    let mut changes = Vec::new();
    let mut n = 0;
    while let Ok(Frame::Video(vf)) = dec.receive_frame() {
        if watch.observe(&dec, &mut stream) {
            changes.push(n);
        }
        assert_frame_matches(&vf, &stream, "watched stream");
        n += 1;
    }
    assert_eq!(n, 10);
    assert_eq!(changes, vec![5], "one change, at frame 5");
}

/// 4:0:0 (libx264 cannot code it): the crate's own encoder. ffprobe
/// reports `yuv420p` for this stream (and for the JVT 4:0:0 conformance
/// streams) because its decoder synthesises grey chroma planes; ours
/// emits the single luma plane §7.4.2.1.1 codes, so the truthful label
/// of the frames is `Gray8`.
#[test]
fn monochrome_answers_gray() {
    use oxideav_h264::encoder::{Encoder, EncoderConfig, YuvFrame};
    let (w, h) = (48u32, 32u32);
    let cfg = EncoderConfig {
        chroma_format_idc: 0,
        profile_idc: 100,
        ..EncoderConfig::new(w, h)
    };
    let y: Vec<u8> = (0..(w * h) as usize)
        .map(|i| (i % 200) as u8 + 16)
        .collect();
    let idr = Encoder::new(cfg).encode_idr(&YuvFrame {
        width: w,
        height: h,
        y: &y,
        u: &[],
        v: &[],
    });
    for threads in [1, 8] {
        let trace = decode_streamed(&idr.annex_b, threads, "mono");
        assert_eq!(trace.len(), 1);
        let p = &trace[0].0;
        assert_eq!(
            (p.width, p.height, p.pixel_format),
            (Some(w), Some(h), Some(PixelFormat::Gray8))
        );
    }
}

/// `separate_colour_plane_flag = 1`: three monochrome planes merged
/// into a 4:4:4 frame, announced as 4:4:4 from the SPS already.
#[test]
fn separate_colour_planes_answer_yuv444() {
    use oxideav_h264::encoder::scp::{ScpConfig, encode_scp_sequence};
    let (w, h) = (32usize, 32usize);
    let plane = |s: usize| -> Vec<u8> { (0..w * h).map(|i| ((i * s) % 200) as u8 + 16).collect() };
    let (a, b, c) = (plane(1), plane(3), plane(7));
    let enc = encode_scp_sequence(
        &ScpConfig {
            width: w as u32,
            height: h as u32,
            qp: 26,
            cabac: false,
            b_frame: false,
            direct_temporal: false,
            transform_8x8: false,
        },
        &[(&a, &b, &c)],
    );
    let mut dec = H264CodecDecoder::new(CodecId::new("h264"));
    let nals = nal_payloads(&enc.annex_b);
    // SPS only: announced from it.
    let mut sps = vec![0, 0, 0, 1];
    sps.extend_from_slice(nals[0]);
    assert_eq!(nals[0][0] & 0x1f, 7);
    dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), sps).with_pts(0))
        .expect("sps");
    assert_eq!(dec.output_pixel_format(), Some(PixelFormat::Yuv444P));
    let trace = decode_streamed(&enc.annex_b, 1, "scp");
    assert_eq!(trace.len(), 1);
    assert_eq!(trace[0].0.pixel_format, Some(PixelFormat::Yuv444P));
    assert_eq!(trace[0].0.width, Some(w as u32));
}

/// `reset` (a seek) keeps the `avcC` parameter sets in force: the
/// decoder decodes again from the next IDR without in-band SPS / PPS,
/// and an unchanged shape keeps the generation.
#[test]
fn reset_keeps_the_avcc_parameter_sets() {
    let name = "yuv420p_70x46_25.h264";
    let (avcc, packets) = to_avcc(&fixture(name));
    let mut params = CodecParameters::video(CodecId::new("h264"));
    params.extradata = avcc;
    let mut dec = make_decoder(&params).expect("make_decoder");
    let mut trace = Vec::new();
    for p in &packets[..3] {
        dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), p.clone()))
            .expect("send");
        drain(&mut *dec, &mut trace, name);
    }
    dec.reset().expect("reset");
    let mut after = Vec::new();
    for p in &packets {
        dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), p.clone()))
            .expect("send");
        drain(&mut *dec, &mut after, name);
    }
    dec.flush().expect("flush");
    drain(&mut *dec, &mut after, name);
    assert_eq!(
        after.len(),
        probe(name).frames,
        "every frame after the seek"
    );
    assert!(after.iter().all(|(_, g)| *g == 0), "same shape, no bump");
    assert_eq!(dec.output_params().and_then(|p| p.width), Some(70));
}
